"""Loans, in a SQLite file shared by every shelf process.

A title is the primary key, so the database itself refuses a second loan of
the same book - two racing `lend` commands cannot both win.
"""
import os
import sqlite3
from contextlib import closing


class AlreadyLent(Exception):
    pass


class NotLent(Exception):
    pass


def db_path():
    return os.environ.get("SHELF_DB", "shelf.db")


def _connect():
    # Autocommit: each statement is its own atomic transaction.
    conn = sqlite3.connect(db_path(), timeout=30, isolation_level=None)
    conn.execute(
        "CREATE TABLE IF NOT EXISTS loans (title TEXT PRIMARY KEY, member TEXT NOT NULL)"
    )
    return conn


def lend(title, member):
    with closing(_connect()) as conn:
        try:
            conn.execute("INSERT INTO loans (title, member) VALUES (?, ?)", (title, member))
        except sqlite3.IntegrityError:
            row = conn.execute("SELECT member FROM loans WHERE title = ?", (title,)).fetchone()
            raise AlreadyLent("%s is already lent to %s" % (title, row[0] if row else "another member"))


def give_back(title):
    with closing(_connect()) as conn:
        if conn.execute("DELETE FROM loans WHERE title = ?", (title,)).rowcount == 0:
            raise NotLent("%s is not lent out" % title)


def holder(title):
    with closing(_connect()) as conn:
        row = conn.execute("SELECT member FROM loans WHERE title = ?", (title,)).fetchone()
    return row[0] if row else None

